1	//! Point types.
2	//!
3	//! Mirrors `Clipper2Lib::Point<T>`, of which `Point64` (64-bit integer
4	//! coordinates) is the instantiation used by `test1.cpp`. `PointD` (double
5	//! coordinates) is provided alongside it because the C++ header exposes the two
6	//! as a pair and callers routinely convert between them.
7	
8	use std::fmt;
9	use std::ops::{Add, Neg, Sub};
10	
11	/// A point with 64-bit signed integer coordinates.
12	///
13	/// The C++ counterpart is `Clipper2Lib::Point64`, a plain aggregate of two
14	/// `int64_t` fields, constructed as `Point64(x, y)`.
15	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
16	pub struct Point64 {
17	    pub x: i64,
18	    pub y: i64,
19	}
20	
21	impl Point64 {
22	    /// The origin, `(0, 0)` — equivalent to the default-constructed `Point64()`.
23	    pub const ORIGIN: Self = Self { x: 0, y: 0 };
24	
25	    /// Constructs a point, matching the C++ `Point64(x, y)` constructor.
26	    #[inline]
27	    pub const fn new(x: i64, y: i64) -> Self {
28	        Self { x, y }
29	    }
30	
31	    /// Rounds a floating-point pair to the nearest integer point.
32	    ///
33	    /// C++ builds `Point64` from `double`s via `std::llround`, which rounds half
34	    /// away from zero — the same rule as Rust's [`f64::round`].
35	    #[inline]
36	    pub fn from_rounded(x: f64, y: f64) -> Self {
37	        Self::new(x.round() as i64, y.round() as i64)
38	    }
39	
40	    /// Translates the point by `(dx, dy)`.
41	    #[inline]
42	    pub fn translate(self, dx: i64, dy: i64) -> Self {
43	        Self::new(self.x + dx, self.y + dy)
44	    }
45	
46	    /// Widens the point to floating-point coordinates.
47	    #[inline]
48	    pub fn to_point_d(self) -> PointD {
49	        PointD::new(self.x as f64, self.y as f64)
50	    }
51	}
52	
53	impl From<(i64, i64)> for Point64 {
54	    #[inline]
55	    fn from((x, y): (i64, i64)) -> Self {
56	        Self::new(x, y)
57	    }
58	}
59	
60	impl From<Point64> for (i64, i64) {
61	    #[inline]
62	    fn from(p: Point64) -> Self {
63	        (p.x, p.y)
64	    }
65	}
66	
67	impl Add for Point64 {
68	    type Output = Self;
69	    #[inline]
70	    fn add(self, rhs: Self) -> Self {
71	        Self::new(self.x + rhs.x, self.y + rhs.y)
72	    }
73	}
74	
75	impl Sub for Point64 {
76	    type Output = Self;
77	    #[inline]
78	    fn sub(self, rhs: Self) -> Self {
79	        Self::new(self.x - rhs.x, self.y - rhs.y)
80	    }
81	}
82	
83	impl Neg for Point64 {
84	    type Output = Self;
85	    #[inline]
86	    fn neg(self) -> Self {
87	        Self::new(-self.x, -self.y)
88	    }
89	}
90	
91	/// Renders the point as `x,y`.
92	///
93	/// Note: this is this crate's own convention for diagnostics. `test1.cpp` never
94	/// streams a `Point64`, so no claim is made here about byte-compatibility with
95	/// the C++ `operator<<`; only [`Path64::size`](crate::path::Path64::size) output
96	/// is contractually reproduced.
97	impl fmt::Display for Point64 {
98	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
99	        write!(f, "{},{}", self.x, self.y)
100	    }
101	}
102	
103	/// A point with `f64` coordinates — the C++ `Clipper2Lib::PointD`.
104	#[derive(Clone, Copy, Debug, Default, PartialEq)]
105	pub struct PointD {
106	    pub x: f64,
107	    pub y: f64,
108	}
109	
110	impl PointD {
111	    /// Constructs a point, matching the C++ `PointD(x, y)` constructor.
112	    #[inline]
113	    pub const fn new(x: f64, y: f64) -> Self {
114	        Self { x, y }
115	    }
116	
117	    /// Rounds to the nearest [`Point64`], half away from zero.
118	    #[inline]
119	    pub fn to_point64(self) -> Point64 {
120	        Point64::from_rounded(self.x, self.y)
121	    }
122	}
123	
124	impl From<(f64, f64)> for PointD {
125	    #[inline]
126	    fn from((x, y): (f64, f64)) -> Self {
127	        Self::new(x, y)
128	    }
129	}
130	
131	impl From<Point64> for PointD {
132	    #[inline]
133	    fn from(p: Point64) -> Self {
134	        p.to_point_d()
135	    }
136	}
137	
138	#[cfg(test)]
139	mod tests {
140	    use super::*;
141	
142	    #[test]
143	    fn new_stores_coordinates_verbatim() {
144	        let p = Point64::new(100, -100);
145	        assert_eq!((p.x, p.y), (100, -100));
146	        assert_eq!(Point64::default(), Point64::ORIGIN);
147	    }
148	
149	    #[test]
150	    fn equality_is_componentwise() {
151	        assert_eq!(Point64::new(0, 0), Point64::from((0, 0)));
152	        assert_ne!(Point64::new(0, 1), Point64::new(1, 0));
153	    }
154	
155	    #[test]
156	    fn arithmetic_matches_cpp_operators() {
157	        let a = Point64::new(3, 4);
158	        let b = Point64::new(10, 20);
159	        assert_eq!(a + b, Point64::new(13, 24));
160	        assert_eq!(b - a, Point64::new(7, 16));
161	        assert_eq!(-a, Point64::new(-3, -4));
162	        assert_eq!(a.translate(-3, -4), Point64::ORIGIN);
163	    }
164	
165	    #[test]
166	    fn rounding_is_half_away_from_zero() {
167	        assert_eq!(Point64::from_rounded(0.5, -0.5), Point64::new(1, -1));
168	        assert_eq!(Point64::from_rounded(1.4, -1.6), Point64::new(1, -2));
169	        assert_eq!(PointD::new(2.5, 3.5).to_point64(), Point64::new(3, 4));
170	    }
171	
172	    #[test]
173	    fn conversions_round_trip() {
174	        let p = Point64::new(100, 100);
175	        assert_eq!(PointD::from(p).to_point64(), p);
176	        assert_eq!(<(i64, i64)>::from(p), (100, 100));
177	    }
178	
179	    #[test]
180	    fn display_is_comma_separated() {
181	        assert_eq!(Point64::new(100, 0).to_string(), "100,0");
182	    }
183	}
