355	#[cfg(test)]
356	mod tests {
357	    use super::*;
358	
359	    /// The exact literal from `test1.cpp`.
360	    fn test1_path() -> Path64 {
361	        Path64::from(vec![
362	            Point64::new(0, 0),
363	            Point64::new(100, 0),
364	            Point64::new(100, 100),
365	            Point64::new(0, 100),
366	        ])
367	    }
368	
369	    #[test]
370	    fn size_of_the_test1_literal_is_four() {
371	        assert_eq!(test1_path().size(), 4);
372	        assert_eq!(format!("{}", test1_path().size()), "4");
373	    }
374	
375	    #[test]
376	    fn size_tracks_insertions_and_keeps_duplicates() {
377	        let mut path = Path64::new();
378	        assert!(path.empty());
379	        assert_eq!(path.size(), 0);
380	        path.push_back(Point64::new(0, 0));
381	        path.push_back(Point64::new(0, 0)); // a vector is not a set
382	        assert_eq!(path.size(), 2);
383	        assert!(!path.empty());
384	    }
385	
386	    #[test]
387	    fn insertion_order_is_preserved() {
388	        let path = test1_path();
389	        assert_eq!(path[0], Point64::new(0, 0));
390	        assert_eq!(path[3], Point64::new(0, 100));
391	        assert_eq!(path.points().last().copied(), Some(Point64::new(0, 100)));
392	    }
393	
394	    #[test]
395	    fn macro_matches_explicit_construction() {
396	        assert_eq!(
397	            path64![(0, 0), (100, 0), (100, 100), (0, 100)],
398	            test1_path()
399	        );
400	        assert_eq!(path64![].size(), 0);
401	        assert_eq!(path64![Point64::new(1, 2)].size(), 1);
402	    }
403	
404	    #[test]
405	    fn conversions_and_iteration_agree_on_length() {
406	        let path = test1_path();
407	        assert_eq!(path.iter().count(), path.size());
408	        assert_eq!(path.to_path_d().size(), 4);
409	        assert_eq!(path.to_path_d().to_path64(), path);
410	        assert_eq!(Vec::from(path.clone()).len(), 4);
411	        assert_eq!(path.clone().into_iter().count(), 4);
412	        assert_eq!(Path64::with_capacity(8).size(), 0);
413	    }
414	
415	    #[test]
416	    fn bounds_cover_every_point() {
417	        let r = test1_path().bounds().expect("non-empty path has bounds");
418	        assert_eq!((r.left, r.top, r.right, r.bottom), (0, 0, 100, 100));
419	        assert_eq!(Path64::new().bounds(), None);
420	    }
421	
422	    #[test]
423	    fn area_of_the_unit_square_literal() {
424	        // A 100x100 square, wound clockwise in screen coordinates.
425	        assert_eq!(test1_path().signed_area2(), 20_000);
426	        assert_eq!(test1_path().area(), 10_000.0);
427	        // Fewer than three points cannot enclose area.
428	        assert_eq!(path64![(0, 0), (1, 1)].area(), 0.0);
429	    }
430	
431	    #[test]
432	    fn area_sign_flips_with_winding() {
433	        let mut reversed = test1_path();
434	        reversed.reverse(); // reaches Vec::reverse through DerefMut
435	        assert_eq!(reversed.signed_area2(), -test1_path().signed_area2());
436	    }
437	
438	    #[test]
439	    fn display_lists_points_space_separated() {
440	        assert_eq!(test1_path().to_string(), "0,0 100,0 100,100 0,100");
441	    }
442	
443	    #[test]
444	    fn paths_containers_count_their_members() {
445	        let mut paths = Paths64::new();
446	        assert!(paths.empty());
447	        paths.push_back(test1_path());
448	        paths.push_back(Path64::new());
449	        assert_eq!(paths.size(), 2);
450	        assert_eq!(paths.total_points(), 4);
451	
452	        let d = PathsD::from(vec![test1_path().to_path_d()]);
453	        assert_eq!(d.size(), 1);
454	        assert_eq!(d[0].size(), 4);
455	        assert!(PathD::new().empty());
456	    }
457	}
